  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$Vrai. Selon l'Urssaf, le gérant ou collège de gérance qui détient au plus 50 % des parts est minoritaire ou égalitaire, donc assimilé salarié ; il faut plus de 50 % pour être travailleur indépendant. Revoir la leçon 1, partie « Explication simple ».$academy_seed$);
