  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$Pour l'artisan ou le commerçant, le revenu pris en compte est plafonné à 48 060 € en 2026, ce qui donne une IJ maximale de 65,84 € bruts. Le calcul 1/730e ne s'applique qu'au revenu plafonné ; le maximum de 197,51 € concerne les professions libérales. Revoir la leçon 2, partie « Exemple ».$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l2, $academy_seed$q06$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$chiffrer-arret-de-travail$academy_seed$, $academy_seed$Cas fictif : une avocate libérale vous annonce une opération qui l'arrêtera six mois. Quel point de vigilance sur le régime obligatoire notez-vous pour l'étude ?$academy_seed$, $academy_seed$["L'Assurance Maladie indemnise au plus 90 jours ; le relais au-delà dépend de sa caisse professionnelle et doit être vérifié","Les IJ sont versées sans limite de durée tant que l'arrêt est prescrit","Elle percevra 197,51 € par jour pendant les six mois, sans autre vérification","Les professions libérales n'ont aucune indemnité journalière du régime obligatoire"]$academy_seed$::jsonb, 3)
