  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$Ameli.fr indique pour le professionnel libéral une durée totale d'arrêt indemnisé limitée à 90 jours ; au-delà, le relais dépend de la caisse de retraite professionnelle, à vérifier sur la source officielle. Le montant de 197,51 € est un maximum, pas un montant acquis. Revoir la leçon 2, partie « Explication simple ».$academy_seed$);
