  values (v_ver, v_l3, $academy_seed$q08$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$audit-couvertures-prevoyance$academy_seed$, $academy_seed$Pour juger si un contrat de prévoyance existant répond au besoin chiffré d'un dirigeant, quelle information est indispensable ?$academy_seed$, $academy_seed$["La franchise applicable et la définition de l'invalidité retenue","Le montant de la cotisation annuelle","La date de souscription du contrat","Le nom du distributeur qui l'a vendu"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$L'audit relève ce qui déclenche et ce qui limite la garantie : franchise, montant, durée, définition de l'invalidité, capital et rentes. La cotisation, la date ou le distributeur ne disent rien de l'écart avec le besoin. Revoir la leçon 3, partie « Explication simple ».$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q09$academy_seed$, $academy_seed$cas_court$academy_seed$, $academy_seed$audit-couvertures-prevoyance$academy_seed$, $academy_seed$Cas fictif : un dirigeant travailleur non salarié détient depuis dix ans un contrat de prévoyance avec une franchise de 90 jours et un capital décès faible. Un collègue propose de résilier et de tout remplacer avant le second rendez-vous. Quelle réponse est conforme à la méthode du cabinet ?$academy_seed$, $academy_seed$["Chiffrer l'écart, envisager un complément, et rappeler qu'un nouveau contrat implique délai d'attente et questionnaire de santé ; la décision relève de l'étude","Résilier immédiatement, un contrat de dix ans étant forcément dépassé","Ne rien faire, un contrat ancien étant une garantie acquise qu'il ne faut jamais toucher","Augmenter d'abord la cotisation pour profiter davantage de la déduction Madelin"]$academy_seed$::jsonb, 3)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$Aucune recommandation ne précède l'étude. Résilier fait perdre une garantie acquise et rouvre délai d'attente et sélection médicale ; ne rien faire ignore l'écart constaté ; la déduction n'est pas un objectif. Revoir la leçon 3, partie « Erreur fréquente ».$academy_seed$);
  insert into public.academy_questions (version_id, lecon_id, cle, type, competence, enonce, choix, difficulte)
  values (v_ver, v_l3, $academy_seed$q10$academy_seed$, $academy_seed$qcm$academy_seed$, $academy_seed$audit-couvertures-prevoyance$academy_seed$, $academy_seed$Cas fictif : un client demande si la cotisation de son contrat de prévoyance Madelin « fait baisser l'impôt ». Quelle réponse est exacte ?$academy_seed$, $academy_seed$["Pour un travailleur non salarié, elle est déductible du bénéfice imposable dans les limites du BOFiP (3,75 % du bénéfice et 7 % du plafond annuel, sans dépasser 3 % de huit plafonds)","Elle est déductible pour tout dirigeant, y compris le président de SAS","Elle est déductible sans aucune limite de montant","Elle ouvre une réduction d'impôt égale au montant de la cotisation"]$academy_seed$::jsonb, 2)
  returning id into v_q;
  insert into public.academy_corriges (question_id, bonne_reponse, explication) values (v_q, 0, $academy_seed$Le cadre Madelin vise les bénéfices de l'activité non salariée (impots.gouv.fr) et la déduction de la prévoyance est plafonnée selon le BOFiP. Il s'agit d'une déduction du bénéfice, pas d'une réduction d'impôt, et l'assimilé salarié n'en relève pas. Revoir la leçon 3, partie « Explication simple ».$academy_seed$);
